function tp(text, o) {            // абзац титульного листа (одинарный интервал, 14 пт)
  o = o || {};
  return new Paragraph({
    alignment: o.align || AlignmentType.CENTER,
    spacing: { before: o.before || 0, after: o.after || 0, line: o.line || 276 },
    indent: { firstLine: 0, left: o.left || 0 },
    keepNext: o.keepNext,
    pageBreakBefore: o.pageBreak,
    tabStops: o.tabs,
    children: [new TextRun({ text, font: FONT, size: o.size || 28, bold: o.bold, underline: o.underline ? {} : undefined })],
  });
}
const cap = (t) => tp('(' + t + ')', { size: 18, after: 100 });   // подпись под линией

